INSERT INTO public.training_flashcards (module_id, front_content, back_content, order_index)
VALUES 
('3875311c-0a12-4d00-a043-e2184aaaf407', 'What is the primary objective of a Mortgage Field Inspector?', 'To verify the occupancy status and physical condition of a property on behalf of the mortgage lender.', 1),
('3875311c-0a12-4d00-a043-e2184aaaf407', 'Define "Occupancy Status".', 'Whether a property is currently inhabited (Occupied) or empty (Vacant).', 2),
('3875311c-0a12-4d00-a043-e2184aaaf407', 'What should you do if you encounter a hostile occupant?', 'Leave the property immediately, ensure your safety, and document the attempt.', 3),
('3875311c-0a12-4d00-a043-e2184aaaf407', 'True or False: You should always enter a property even if it looks unsafe.', 'False. Safety is the top priority. Do not enter if unsafe.', 4);
INSERT INTO public.training_flashcards (module_id, front_content, back_content, order_index)
VALUES 
('bffcfb09-5665-4c1b-82df-8ae02653facb', 'What is the required photo orientation?', 'Horizontal (Landscape). Vertical photos are generally prohibited.', 1),
('bffcfb09-5665-4c1b-82df-8ae02653facb', 'What is the minimum photo resolution?', '1024 x 768 pixels.', 2),
('bffcfb09-5665-4c1b-82df-8ae02653facb', 'What is a "Context Shot"?', 'A wide-angle photo that shows the surrounding area of a specific detail or damage to provide perspective.', 3),
('bffcfb09-5665-4c1b-82df-8ae02653facb', 'Why must you avoid taking photos of people?', 'To protect privacy and comply with privacy laws and client requirements.', 4),
('bffcfb09-5665-4c1b-82df-8ae02653facb', 'True or False: You should edit your photos to make them look better.', 'False. Photos must be original, unaltered, and contain valid metadata.', 5);
